fn v50_fold_dive_episode(&mut self, _version: usize, _tps: usize, aborted: bool, end_reason: u8)
// _version/_tps 는 IR 에서 poison(완전 소거). 실인자는 (self, aborted, end_reason) 3개뿐.

// ── [1] '헛수고한 다이브'면 포기 시각을 갱신 (src 131~141) ──
// IR: %11 = select(is_some, in_range_ticks==0, false) → true 면 138 블록, false 면 곧장 [2]로
let live = self.v50_dive_ep_live;                  // Option<V50DiveEpLive> @ +0x570, 니치 -1 = None
if live.is_some()
   && live.in_range_ticks == 0                     // +0x598 == 0  (※이 비교만 !dbg 소실 — unknown 참조)
   && live.team_holder_ticks == 0                  // +0x5a8 == 0  (src:138)
   && end_reason != 7                              // (src:139)
{
    // src:140  — umax 로 접힌 Ord::max
    self.last_dive_abandon_tick = max(self.last_dive_abandon_tick /* +0x1480 */,
                                      live.last_tick /* +0x588 */);
}
// ⚠[1] 은 live 를 소비하지 않는다(as_ref). 조건이 어떻든 [2],[3] 은 항상 실행된다.

// ── [2] 종료 시점의 BigPlan 이름을 1바이트 코드로 접음 (src 145~153) ──
let n: String = self.plan.get_name();              // self.plan(BigPlan,384B) @ +0x5e8
let end_plan: u8 =
     if n.starts_with("PassiveLine")   { 1 }       // src:146
else if n.starts_with("PassiveJungle") { 2 }       // src:147
else if n.starts_with("LineGank")      { 3 }       // src:148
else if n.contains("Epic")             { 4 }       // src:149  (str::contains → Pattern::is_contained_in)
else if n.contains("Serpen")           { 5 }       // src:150
else if n.starts_with("ActiveRecall")  { 6 }       // src:151  ┐ 두 블록(%56,%61)이 같은 phi 값 6
else if n.starts_with("Recall")        { 6 }       // src:151  ┘ = 소스는 `||` 한 줄
else if n.starts_with("Battle")        { 7 }       // src:152
else if n.contains("Nexus")            { 8 }       // src:153
else                                   { 9 };      // src:153 (select %70 ? 8 : 9)
drop(n);                                           // src:155 (String/RawVec drop glue)

// ── [3] live 를 꺼내 확정 에피소드로 push (src 156~169) ──
// IR: 먼저 live 의 20개 필드를 전부 레지스터로 로드한 뒤 +0x570 에 -1(None) 을 store.
//     = core::mem::replace(&mut self.v50_dive_ep_live, None)  (Option::take, src:156)
let taken = self.v50_dive_ep_live.take();
if taken.is_none() { return; }                     // 로드해 둔 옛 태그가 -1 이면 그대로 종료

// src:157  Vec::push_mut — len==cap 이면 RawVec::grow_one, 그다음 ptr.add(len) 에 ptr::write, len+=1
self.v50_dive_episodes.push(V50DiveEpisode {        // elem 104B
    max_catch_break:    live.max_catch_break,       // +0x5c8 → +0x00
    uncatch_total:      live.uncatch_total,         // +0x5d0 → +0x08
    start_tick:         live.start_tick,            // +0x580 → +0x10
    end_tick:           live.last_tick,             // +0x588 → +0x18   ★live.last_tick 이 end_tick 이 된다
    ep_ticks:           live.ep_ticks,              // +0x590 → +0x20
    in_range_ticks:     live.in_range_ticks,        // +0x598 → +0x28
    holder_ticks:       live.holder_ticks,          // +0x5a0 → +0x30
    team_holder_ticks:  live.team_holder_ticks,     // +0x5a8 → +0x38
    minion_cover_ticks: live.minion_cover_ticks,    // +0x5b0 → +0x40
    soaked_hp:          live.soaked_hp,             // +0x5b8 → +0x48
    start_race_adv:     live.start_race_adv,        // +0x5dc → +0x50 (i32)
    target_pos:         live.target_pos,            // +0x5d8 → +0x54 (i32/Position)
    abort_src:          if aborted { self.v50_dive_ep_abort_src /* +0x1811 */ } else { 0 },  // src:167
    start_model:        live.start_model,           // +0x5e2 → +0x59
    start_na:           live.start_na,              // +0x5e3 → +0x5a
    start_ne:           live.start_ne,              // +0x5e4 → +0x5b
    start_tgt_hp:       live.start_tgt_hp,          // +0x5e5 → +0x5c
    end_reason:         end_reason,                 // 파라미터 그대로 → +0x5d
    end_plan:           end_plan,                   // [2]의 코드 → +0x5e
    tower:              live.tower,                 // +0x5e1 → +0x5f
    start_in_range:     live.start_in_range & 1,    // +0x5e0 → +0x60 (bool 정규화)
    aborted:            aborted as u8,              // 파라미터 → +0x61
});
// ⚠live 의 prev_holder_hp(+0x570,16B)·gap_ticks(+0x5c0) 는 읽지 않는다 = 에피소드에 안 남는다.
